-- Fixes found while testing the action enchants (2 Nov).
-- Arcane Charge (282881): the damage part of its helper spell 282883 hit enemies around the caster, but it is
-- cast as Charge starts, while the caster is still far away, so it hit nothing. It now hits enemies around the
-- Charge target instead. Owned only if spell_dbc has no row for it already.
INSERT IGNORE INTO `wcme_owned` (`tbl`, `id`) SELECT 'spell_dbc', 282883 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `spell_dbc` WHERE `ID` = 282883);
